(() => {
  const ALLOWED = new Set(["approvedVisits", "usedVisits", "startDate", "endDate", "visitDate"]);
  function checkAuthorization(input) {
    for (const key of Object.keys(input)) {
      if (!ALLOWED.has(key)) {
        throw new Error("unknown field: " + key);
      }
    }
    const { approvedVisits, usedVisits, startDate, endDate, visitDate } = input;
    const inWindow = startDate <= visitDate && visitDate <= endDate;
    const covered = inWindow && usedVisits < approvedVisits;
    const remaining = covered ? approvedVisits - usedVisits - 1 : approvedVisits - usedVisits;
    return { covered, remaining };
  }
  return { checkAuthorization };
})()

