build.unitScript:
const base = { approvedVisits: 6, startDate: "2026-02-01", endDate: "2026-04-30" };
test("visit on the end date with 4 of 6 used is covered and leaves 1", () => {
  assert.deepEqual(code.checkAuthorization({ ...base, usedVisits: 4, visitDate: "2026-04-30" }), { covered: true, remaining: 1 });
});
test("visit one day after the end date is not covered and leaves 2", () => {
  assert.deepEqual(code.checkAuthorization({ ...base, usedVisits: 4, visitDate: "2026-05-01" }), { covered: false, remaining: 2 });
});
test("visit inside the window with all 6 used is not covered and leaves 0", () => {
  assert.deepEqual(code.checkAuthorization({ ...base, usedVisits: 6, visitDate: "2026-03-15" }), { covered: false, remaining: 0 });
});
test("visit on the start date with 4 of 6 used is covered and leaves 1", () => {
  assert.deepEqual(code.checkAuthorization({ ...base, usedVisits: 4, visitDate: "2026-02-01" }), { covered: true, remaining: 1 });
});
test("visit one day before the start date is not covered and leaves 2", () => {
  assert.deepEqual(code.checkAuthorization({ ...base, usedVisits: 4, visitDate: "2026-01-31" }), { covered: false, remaining: 2 });
});
test("an input field outside the contract is rejected by name", () => {
  assert.throws(() => code.checkAuthorization({ ...base, usedVisits: 4, visitDate: "2026-03-01", patientId: "x" }), /unknown field: patientId/);
});

build.testScript:
test("visit on the inclusive end date is covered and leaves 1", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-30"
  });
  assert.deepEqual(result, { covered: true, remaining: 1 });
});
test("visit one day after the end date is not covered and leaves 2", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-05-01"
  });
  assert.deepEqual(result, { covered: false, remaining: 2 });
});
test("visit on the inclusive start date is covered and leaves 1", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-01"
  });
  assert.deepEqual(result, { covered: true, remaining: 1 });
});
test("visit inside the window when used equals approved is not covered and leaves 0", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 6,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-10"
  });
  assert.deepEqual(result, { covered: false, remaining: 0 });
});
test("visit one day before the start date is not covered and leaves 2", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-01-31"
  });
  assert.deepEqual(result, { covered: false, remaining: 2 });
});
test("visit one day after the start date is covered and leaves 1", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-02"
  });
  assert.deepEqual(result, { covered: true, remaining: 1 });
});
test("visit one day before the end date is covered and leaves 1", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-29"
  });
  assert.deepEqual(result, { covered: true, remaining: 1 });
});
test("visit in the middle of the window is covered and leaves 6", function() {
  var result = code.checkAuthorization({
    approvedVisits: 9,
    usedVisits: 2,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-15"
  });
  assert.deepEqual(result, { covered: true, remaining: 6 });
});
test("visit when used is one below approved is covered and leaves 0", function() {
  var result = code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 5,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-20"
  });
  assert.deepEqual(result, { covered: true, remaining: 0 });
});
test("one approved visit on the first day with none used is covered and leaves 0", function() {
  var result = code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: "2026-08-01",
    endDate: "2026-08-31",
    visitDate: "2026-08-01"
  });
  assert.deepEqual(result, { covered: true, remaining: 0 });
});
test("zero approved and zero used is not covered and leaves 0", function() {
  var result = code.checkAuthorization({
    approvedVisits: 0,
    usedVisits: 0,
    startDate: "2026-08-01",
    endDate: "2026-08-31",
    visitDate: "2026-08-15"
  });
  assert.deepEqual(result, { covered: false, remaining: 0 });
});
test("visit on the last day of a 31 day month is covered and leaves 1", function() {
  var result = code.checkAuthorization({
    approvedVisits: 3,
    usedVisits: 1,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-01-31"
  });
  assert.deepEqual(result, { covered: true, remaining: 1 });
});
test("December 31 inside a year spanning window is covered and leaves 2", function() {
  var result = code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2025-12-15",
    endDate: "2026-01-15",
    visitDate: "2025-12-31"
  });
  assert.deepEqual(result, { covered: true, remaining: 2 });
});
test("January 1 inside a year spanning window is covered and leaves 3", function() {
  var result = code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 0,
    startDate: "2025-12-15",
    endDate: "2026-01-15",
    visitDate: "2026-01-01"
  });
  assert.deepEqual(result, { covered: true, remaining: 3 });
});
test("leap day as a single day window is covered and leaves 1", function() {
  var result = code.checkAuthorization({
    approvedVisits: 3,
    usedVisits: 1,
    startDate: "2024-02-29",
    endDate: "2024-02-29",
    visitDate: "2024-02-29"
  });
  assert.deepEqual(result, { covered: true, remaining: 1 });
});
test("an unknown notes field throws an error naming that field", function() {
  assert.throws(function() {
    code.checkAuthorization({
      approvedVisits: 6,
      usedVisits: 4,
      startDate: "2026-02-01",
      endDate: "2026-04-30",
      visitDate: "2026-03-15",
      notes: "x"
    });
  }, /^unknown field: notes$/);
});

